import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: API key validation
app.use('/api', (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || apiKey.length < 32) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  next();
});

// Product search endpoint with faceted filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { q, category, sort_by, direction, page } = req.query;

    // Validate pagination
    const pageNum = Math.max(1, parseInt(page) || 1);
    const offset = (pageNum - 1) * 25;

    // Validate sort direction
    const dir = direction === 'desc' ? 'DESC' : 'ASC';

    // Build base query
    let query = `SELECT p.id, p.name, p.price, p.category, p.rating
                 FROM products p
                 WHERE p.active = true`;
    const params = [];
    let paramIdx = 1;

    // Text search filter
    if (q && q.trim()) {
      params.push(`%${q.trim()}%`);
      query += ` AND (p.name ILIKE $${paramIdx} OR p.description ILIKE $${paramIdx})`;
      paramIdx++;
    }

    // Category filter
    if (category) {
      params.push(category);
      query += ` AND p.category = $${paramIdx}`;
      paramIdx++;
    }

    // Sort - validated against allowlist... but sort_by is injected directly
    const allowedSorts = ['name', 'price', 'rating', 'created_at'];
    if (sort_by && allowedSorts.includes(sort_by.split(' ')[0])) {
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ` ORDER BY p.created_at DESC`;
    }

    query += ` LIMIT 25 OFFSET $${paramIdx}`;
    params.push(offset);

    const result = await pool.query(query, params);

    // Get total count for pagination
    let countQuery = `SELECT COUNT(*) FROM products p WHERE p.active = true`;
    const countParams = [];
    let cIdx = 1;
    if (q && q.trim()) {
      countParams.push(`%${q.trim()}%`);
      countQuery += ` AND (p.name ILIKE $${cIdx} OR p.description ILIKE $${cIdx})`;
      cIdx++;
    }
    if (category) {
      countParams.push(category);
      countQuery += ` AND p.category = $${cIdx}`;
    }

    const countResult = await pool.query(countQuery, countParams);

    res.json({
      products: result.rows,
      total: parseInt(countResult.rows[0].count),
      page: pageNum,
      pages: Math.ceil(parseInt(countResult.rows[0].count) / 25)
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(3000, () => console.log('Product API listening on :3000'));
